def count_special_zero_one_two_subsequences(nums):
    mod = 1_000_000_007
    zeros = ones = twos = 0
    for value in nums:
        if value == 0:
            zeros = (2 * zeros + 1) % mod
        elif value == 1:
            ones = (2 * ones + zeros) % mod
        else:
            twos = (2 * twos + ones) % mod
    return twos

